class Solution:
    def minDeletions(self, nums: list[int]) -> int:
        return sum(x == y for x, y in pairwise(nums))

class Solution {
    public int minDeletions(int[] nums) {
        int ans = 0;
        for (int i = 1; i < nums.length; ++i) {
            if (nums[i] == nums[i - 1]) {
                ++ans;
            }
        }
        return ans;
    }
}

